/* Advanced7 — preserve value, remove owned waste, measure commitments hourly. */
(()=>{
 const N=AG.aws.n,copy=x=>JSON.parse(JSON.stringify(x)),canon=v=>Array.isArray(v)?v.map(canon):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,canon(v[k])])):v,same=(a,b)=>JSON.stringify(canon(a))===JSON.stringify(canon(b));
 const ACCT='444444444444',R='us-east-1',PROD='vol-0c027000000000001',WASTE='vol-0c027000000000002',AUDIT='vol-0c027000000000003',OLD='snap-0c0270000000000aa',KEEP='snap-0c0270000000000bb',NEW='snap-0c027000000000001',IDLE='eipalloc-0c02700000000001',LIVEIP='eipalloc-0c02700000000002';
 const TOPIC=`arn:aws:sns:${R}:${ACCT}:cost-alerts`,BNAME='shopkaro-monthly',LOG='/shopkaro/dev',COMPLIANCE='/shopkaro/audit';
 const POLICY={Version:'2012-10-17',Statement:[{Effect:'Allow',Principal:{Service:'budgets.amazonaws.com'},Action:'SNS:Publish',Resource:TOPIC,Condition:{StringEquals:{'aws:SourceAccount':ACCT},ArnLike:{'aws:SourceArn':`arn:aws:budgets::${ACCT}:*`}}}]};
 const BUDGET={BudgetName:BNAME,BudgetLimit:{Amount:'1000',Unit:'USD'},TimeUnit:'MONTHLY',BudgetType:'COST'},NOTICE={NotificationType:'ACTUAL',ComparisonOperator:'GREATER_THAN',Threshold:80,ThresholdType:'PERCENTAGE'},SUBS=[{SubscriptionType:'SNS',Address:TOPIC}],NOTIFICATIONS=[{Notification:NOTICE,Subscribers:SUBS}];
 const file=x=>({content:JSON.stringify(x,null,2)});
 function seed(){return {costMode:true,costSnapshotSeq:0,region:R,callerIdentity:{Account:ACCT,Arn:`arn:aws:iam::${ACCT}:role/platform-engineer`},
  vpcs:[{id:'vpc-0c027000000000001',cidr:'10.27.0.0/16'}],instances:[{id:'i-0c027000000000001',name:'orders-1a',state:'running',az:R+'a'},{id:'i-0c027000000000002',name:'orders-1b',state:'running',az:R+'b'}],
  volumes:[{id:PROD,name:'orders',type:'gp2',size:1000,iops:3000,throughput:250,encrypted:true,state:'in-use',attachedTo:'i-0c027000000000001',testData:['TEST-order-27','original-orders-checksum'],tags:{Owner:'orders',Env:'prod'}},{id:WASTE,name:'retired-import',type:'gp2',size:200,iops:600,throughput:128,encrypted:true,state:'available',attachedTo:null,testData:['TEST-legacy-invoice-27'],tags:{Owner:'warehouse',ApprovedDelete:'true'}},{id:AUDIT,name:'audit',type:'gp3',size:100,iops:3000,throughput:125,encrypted:true,state:'in-use',attachedTo:'i-0c027000000000002',testData:['TEST-audit-27'],tags:{Owner:'security',Env:'prod'}}],
  snapshots:[{id:OLD,volumeId:WASTE,size:200,encrypted:true,state:'completed',description:'Expired approved TEST import snapshot',testData:['OLD-incomplete-import'],approvedDelete:true},{id:KEEP,volumeId:PROD,size:1000,encrypted:true,state:'completed',description:'Last approved recovery point; preserve',testData:['TEST-order-27','original-orders-checksum']}],
  addresses:[{allocationId:IDLE,publicIp:'198.51.100.27',instanceId:null},{allocationId:LIVEIP,publicIp:'198.51.100.28',instanceId:'i-0c027000000000001',associationId:'eipassoc-0c02700000000001'}],
  logGroups:[{name:LOG,events:['TEST-current-dev-log-27']},{name:COMPLIANCE,retention:90,events:['TEST-audit-log-27']}],topics:[{name:'cost-alerts',arn:TOPIC,policy:copy(POLICY)}],budgets:[],costRead:null,costUsageGroups:{'2026-09-01':[{key:'BoxUsage',usd:'4181.82'},{key:'Network-Processing-Transfer',usd:'500.00'},{key:'Storage-Other',usd:'2136.36'}],'2026-10-01':[{key:'BoxUsage',usd:'4181.82'},{key:'Network-Processing-Transfer',usd:'12500.00'},{key:'Storage-Other',usd:'3772.73'}]},
  costHistory:[{TimePeriod:{Start:'2026-09-01',End:'2026-10-01'},Total:{UnblendedCost:{Amount:'6818.18',Unit:'USD'}},Estimated:false},{TimePeriod:{Start:'2026-10-01',End:'2026-11-01'},Total:{UnblendedCost:{Amount:'20454.55',Unit:'USD'}},Estimated:true}]};}
 const base=seed(),volume=a=>a.volumes.find(v=>v.id===PROD);
 function core(a){const p=volume(a),old=base.volumes[0];return a.costMode===true&&a.region===R&&same(a.callerIdentity,base.callerIdentity)&&same(a.instances,base.instances)&&same(a.vpcs,base.vpcs)&&!!p&&['id','name','size','encrypted','state','attachedTo','testData','tags'].every(k=>same(p[k],old[k]))&&same(a.volumes.find(v=>v.id===AUDIT),base.volumes[2])&&same(a.snapshots.find(s=>s.id===KEEP),base.snapshots[1])&&same(a.addresses.find(ip=>ip.allocationId===LIVEIP),base.addresses[1])&&same(a.logGroups.find(g=>g.name===COMPLIANCE),base.logGroups[1])&&same(a.costHistory,base.costHistory)&&same(a.costUsageGroups,base.costUsageGroups);}
 function cleaned(a){const p=volume(a),g=a.logGroups.find(g=>g.name===LOG);return core(a)&&a.volumes.length===2&&!a.volumes.some(v=>v.id===WASTE)&&p.type==='gp3'&&p.iops===3000&&p.throughput===250&&!a.snapshots.some(s=>s.id===OLD)&&a.snapshots.some(s=>s.id!==OLD&&s.volumeId===WASTE&&s.state==='completed'&&s.encrypted&&same(s.testData,base.volumes[1].testData))&&a.addresses.length===1&&!a.addresses.some(ip=>ip.allocationId===IDLE)&&!!g&&g.retention===14&&same(g.events,base.logGroups[0].events)&&a.topics.length===1&&AG.costTopicAllowed(a,TOPIC);}
 function budgetReady(a){const b=a.budgets.find(b=>b.definition.BudgetName===BNAME);return !!b&&Number(b.definition.BudgetLimit.Amount)===1000&&b.definition.BudgetLimit.Unit==='USD'&&b.definition.TimeUnit==='MONTHLY'&&b.definition.BudgetType==='COST'&&b.notifications.some(n=>Object.keys(NOTICE).every(k=>n.Notification[k]===NOTICE[k])&&same(n.Subscribers,SUBS))&&AG.costTopicAllowed(a,TOPIC);}
 const tasks=[{text:'Original two-AZ instances, production/audit volumes + TEST data, last-good snapshot, live EIP aur audit 90-day logs preserve',check:s=>core(s.account)},{text:'Fresh completed import-volume snapshot preserve; approved retired volume/old snapshot/idle EIP remove; prod gp3 remains 1000 GiB/3000 IOPS/250 MiB/s; dev 14-day retention',check:s=>cleaned(s.account)},{text:'Monthly USD 1000 COST budget + ACTUAL 80% SNS, scoped topic policy; final current full describe-budget read',check:s=>cleaned(s.account)&&budgetReady(s.account)&&AG.costCurrentRead(s.account,'budget')}];
 const solution=[`aws ec2 create-snapshot --volume-id ${WASTE} --description preserve-import-TEST`,`aws ec2 wait snapshot-completed --snapshot-ids ${NEW}`,`aws ec2 delete-volume --volume-id ${WASTE}`,`aws ec2 modify-volume --volume-id ${PROD} --volume-type gp3 --iops 3000 --throughput 250`,`aws ec2 release-address --allocation-id ${IDLE}`,`aws ec2 delete-snapshot --snapshot-id ${OLD}`,`aws logs put-retention-policy --log-group-name ${LOG} --retention-in-days 14`,`aws budgets create-budget --account-id ${ACCT} --budget file://budget.json --notifications-with-subscribers file://notifications.json`,`aws budgets describe-budget --account-id ${ACCT} --budget-name ${BNAME}`];
 function interviewSeed(){const a=seed();a.volumes=a.volumes.filter(v=>v.id!==WASTE);Object.assign(volume(a),{type:'gp3',iops:3000,throughput:250});a.snapshots=a.snapshots.filter(s=>s.id!==OLD);a.snapshots.push({id:NEW,volumeId:WASTE,size:200,encrypted:true,state:'completed',description:'preserved TEST import',testData:copy(base.volumes[1].testData)});a.costSnapshotSeq=1;a.addresses=a.addresses.filter(ip=>ip.allocationId!==IDLE);a.logGroups[0].retention=14;a.topics[0].policy={Version:'2012-10-17',Statement:[]};a.budgets=[{definition:copy(BUDGET),notifications:[]}];return a;}
 const isolution=[`aws sns set-topic-attributes --topic-arn ${TOPIC} --attribute-name Policy --attribute-value file://budget-topic-policy.json`,`aws budgets create-notification --account-id ${ACCT} --budget-name ${BNAME} --notification file://threshold80.json --subscribers file://subscribers.json`,`aws budgets describe-notifications-for-budget --account-id ${ACCT} --budget-name ${BNAME}`];
 const itasks=[{text:'Original optimized resource/data/retention configuration preserved; safe SNS publish policy for this account/budget',check:s=>cleaned(s.account)},{text:'Budget has ACTUAL 80% notice with correct SNS subscriber; final current full notification read',check:s=>cleaned(s.account)&&budgetReady(s.account)&&AG.costCurrentRead(s.account,'notifications')}];
 const Q=(q,right,wrong,answer,explain)=>{const choices=wrong.slice();choices.splice(answer,0,right);return {q,choices,answer,explain};};
 const table=(heads,rows)=>'<div class="tbl-wrap" tabindex="0" role="region" aria-label="Cost comparison table"><table class="swipe-table"><tr>'+heads.map(h=>'<th>'+h+'</th>').join('')+'</tr>'+rows.map(r=>'<tr>'+r.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')+'</table></div><p>Phone: table focus karke arrow keys ya side swipe use karo.</p>';
 function plan(k){const discount=k.term===0?.30:.45,coverage=60*k.coverage/100,C=coverage*(1-discount),factor=1-k.drop/100,peak=100*factor,low=60*factor,h=730,od=(peak/3+low*2/3)*h,paid=C*h,total=paid+(Math.max(0,peak-coverage)/3+Math.max(0,low-coverage)*2/3)*h,wasted=(Math.max(0,C-peak*(1-discount))/3+Math.max(0,C-low*(1-discount))*2/3)*h,saving=(od-total)/od*100,waste=paid?wasted/paid*100:0;return {discount,C,od,total,wasted,saving,waste,ok:k.drop>=30&&saving>=25-1e-8&&waste<=5+1e-8};}
 AG.costCommitmentPlan=plan;
 const nodes=[N('dev',165,85,{label:'CFO / owner'}),N('cw',500,85,{label:'Bill by usage'}),N('nat',825,85,{label:'NAT processing'}),N('ebs',165,280,{label:'EBS + backup'}),N('ec2',500,280,{label:'Dev compute'}),N('s3',825,280,{label:'S3 gateway'}),N('sns',500,440,{label:'Budget alert'})],edges=[{from:'dev',to:'cw'},{from:'cw',to:'nat'},{from:'cw',to:'ebs'},{from:'cw',to:'ec2'},{from:'nat',to:'s3'},{from:'cw',to:'sns'}];
 AG.registerLevels('advanced',[{id:'cost',icon:'💰',title:'Cost — waste hatao, value bachao',badge:'Paisa Prabhu',objectives:['Meters aur usage type se bill ka driver dhoondho','Performance, backup aur HA bachakar cleanup/rightsize karo','Hourly commitment ko downturn aur unused spend ke saath calculate karo','Budget notification, attribution aur cost per order ka feedback loop banao'],
 hook:{when:'ShopKaro after Series A — fictional course story',title:'₹6 lakh se ₹18 lakh — orders sirf 50% badhe',text:'4 mahine mein ShopKaro ka bill triple hua. CFO 40% cut maang raha hai, par Mahasale ki availability aur invoice data compromise nahi honge. Ravi ko sirf "CPU low" aur "Reserved le lo" se jawab nahi milega: warehouse imports, S3 traffic through NAT aur forgotten disks ka owner chahiye.',mission:'Recorded bill ko usage types tak kholo. Local inventory slice mein approved waste remove karo, backup/production value preserve karo aur Budget alert configure karo. Limited EBS/EIP estimate actual total bill saving ka proof nahi; billing history cleanup ke baad turant rewrite nahi hoti.'},
 steps:[
 {q:'Bill badha — pehle kis unit ko dekhein?',analogy:'Bijli ka kWh, paani ka tanker aur highway ka toll ek hi meter nahi. Cloud bill mein compute hours, stored GiB, requests aur transferred GB alag line items hain.',body:'<p>Cost = quantity × rate, phir discounts/credits/tax adjustments. 1000 GiB EBS aur 1000 GB internet egress ko same unit-price mat do. <b>Cost per successful order</b> = relevant total cost / successful orders; failed retries denominator ko inflate nahi karein.</p><pre>Fictional: ₹6,00,000 / 1,00,000 orders = ₹6/order\n₹18,00,000 / 1,50,000 orders = ₹12/order</pre>',points:['Volume50% bada, cost/order double: waste/architecture/pricing mix investigate karo; har growth overspend nahi.','Galti jo sab karte hain: monthly total dekhkar every EC2 instance downsize karna.','Hands-on: dry run mein bill-by-usage panel padho; triage mein usage quantity compare karo.'],asli:'Pehle cost ka unit aur workload outcome; phir discount.'},
 {q:'Cost Explorer, exports, tags aur anomaly kaunsa sawal solve karte hain?',analogy:'Bank statement trend dikhata hai; itemized shop ledger receipt tak le jaata hai; team name payment ka owner batata hai.',body:table(['Need','Tool','Boundary'],[['Trend/service/usage type','Cost Explorer','Billing data delayed; resource change ka immediate cost meter nahi.'],['Detailed repeatable analytics','AWS Data Exports / CUR2.0','S3 export + SQL analysis; access/cost/schema manage karo.'],['Team ownership','Activated cost allocation tag keys','Resource tag lagana aur billing activation alag actions.'],['Unexpected change','Cost Anomaly Detection','ML-based billing anomaly; delayed, application latency alert nahi.'],['Threshold/forecast','AWS Budgets','Notification/action policy; real-time universal spending cap nahi.']]),points:['User-defined tags discovery up to 24 hours, activation up to 24 hours; historical backfill ko automatic assume mat karo.','CE refresh at least daily; paginated API request approx$0.01. Anomaly detection billing latency inherit karta hai.','Production me kya hota hai: untagged shared NAT/logs ka owner nahi milta; cost categories/allocation rules decide karo.','Hands-on: optional ce get-cost-and-usage se clearly fictional recorded history padho.'],asli:'Attribution, anomaly aur threshold alag jobs hain; billing data time lag rakhta hai.'},
 {q:'Data transfer compute se zyada kyun ho sakta hai?',analogy:'Samaan sasta, lekin har shipment border aur toll cross kare toh delivery bill bada. Network path quantity aur charging points decide karta hai.',body:table(['Path','Potential meter','Decision'],[['Private app → S3 via NAT','NAT hourly + processedGB, possible transfer','Same-Region S3 gateway endpoint route review.'],['App AZ-a → cache AZ-b','Applicable cross-AZ transfer','Locality + HA topology compare; replica/consistency tradeoff.'],['Region A → Region B','Inter-Region transfer + service replication','DR/RPO value ke against price; replication mat blindly hatao.'],['Origin → internet users','Egress + CDN requests/cache effects','CloudFront cache hit/origin egress math compare.']]),points:['S3/DynamoDB gateway endpoints ka extra endpoint charge nahi; correct route tables associate karo.','Same Region service exceptions aur managed-service paths differ; every cross-AZ hop ke liye same universal rate mat quote karo.','Galti jo sab karte hain: NAT delete karna while private app ko third-party internet APIs chahiye.','Hands-on: triage mein EC2 hours unchanged, cross-AZ bytes up ka clue pakdo.'],asli:'Quantity aur full path map karo; HA ko cost fix ke naam par mat todo.'},
 {q:'Right-size karte waqt value kaise preserve karein?',analogy:'Truck ka engine chhota karne se pehle load, road aur delivery deadline dekho. Khaali highway ki CPU reading city rush ka proof nahi.',body:'<p>CPU + memory + network + storageIO + peak latency + headroom dekho. EC2 memory metrics ko agent/integration chahiye. Compute Optimizer EC2 recommendations ke liye generally past 14 days mein at least 30 hours metrics chahiye; insufficient data recommendation nahi.</p><p>US East N.Virginia approx EBS: gp2$0.10/GiB-month; gp3$0.08, baseline3000 IOPS/125 MiB/s. Extra IOPS$0.005/IOPS-month; extra throughput$0.04/MiB/s-month. 1000 GiB gp2$100 → gp3(3000 IOPS,250 MiB/s)$85, approx15% saving. Capacity-only20% ko full bill20% mat bolo.</p>',points:['gp3 conversion mein explicit performance target aur actual readback dekho; source/CLI default behavior par depend mat karo.','Unattached EBS mein valuable data ho sakta hai: owner approval + completed preservation snapshot, phir delete. Snapshot billing incremental changed blocks par; VolumeSize se actual billedGB infer mat karo.','AWS public IPv4 idle aur associated dono approx$0.005/hour;730 hours≈$3.65≈₹321 per address.','Hands-on: terminal prod volume sameID/size/encryption/data ke saath3000 IOPS/250 MiB/s par rakho.'],asli:'Cost kam, required performance/backup/HA same; CPU percentage akela decision nahi.'},
 {q:'Savings Plans, RIs aur break-even kaise compare karein?',analogy:'Monthly tiffin minimum bill lo toh unused lunches ka paisa wapas nahi. Weekend ki bachi commitment Monday ko carry nahi hoti.',body:table(['Commitment','Coverage / advertised ceiling','Boundary'],[['Compute SP (1/3 year)','Up to66%; EC2 across families/Regions, Fargate, Lambda','Hourly$ commitment; database usage excluded.'],['EC2 Instance SP (1/3 year)','Up to72%; selected family + Region','Size/OS flexibility within scope; no capacity reservation.'],['Database SP (1 year, no upfront)','Up to35%; eligible database provisioned/serverless usage','Eligible generations/services check; no double discount with same-usage RI.'],['Service RIs / reservations','Service-specific contract/rates','Not one universal72% DB rate; compare actual eligible quote.']]),points:['Savings Plans commit actual discounted USD/hour par hota hai; On-Demand equivalent coverage se convert karke math karo.','Hypothetical unit: OD $1/hour, committed rate $0.65/hour. Dedicated usage break-even65% of hours; dev8×5/(24×7)≈24% weekly hours ⇒ scheduled OD often cheaper for isolated workload. Existing aggregate eligible usage result badal sakta hai.','Unused hourly commitment expires; peak, rightsizing aur downturn forecast ke baad buy karo.','Hands-on: planner rates hypothetical hain; actual SP purchase nahi hoti.'],asli:'Highest advertised discount se pehle hourly utilization aur lock-in risk dekho.'},
 {q:'Spot sasta hai — har workload par kyun nahi?',analogy:'Last-minute cheap bus seat mil sakti hai, par bus ka owner seat wapas maang sakta hai. Parcel retry ho sakta hai; uncheckpointed payment transaction nahi.',body:'<p>EC2 Spot up to90% off advertised; current price aur capacity vary. Retry/checkpoint/idempotency chahiye. Stop/terminate notice generally2 minutes, best effort; hibernation immediately start hota hai, two-minute window nahi. EventBridge/IMDS notice handle karo.</p>',points:['Multiple acceptable instance types/AZ pools + price-capacity-optimized allocation; one cheapest pool pe depend mat karo.','Production me kya hota hai: retry storm + lost checkpoints discount se zyada cost/latency la sakte hain.','SP discount Spot par stack nahi hota. OD base + Spot workers/surge workload suitability se choose karo.','Hands-on: bins mein retry-safe batch vs uninterrupted workload ko alag pricing path do.'],asli:'Interruptions tolerate karna application design ka property hai, price tag ka nahi.'},
 {q:'Dev ko raat mein stop karna kitna bachata hai?',analogy:'Office band hone par AC band karo; office rent aur warehouse ka rent phir bhi jaata hai.',body:'<p>Business-hours dev: schedule stop/start, timezone/holidays, owner override aur state persistence decide karo. EC2 stopped hone par instance compute charge ruk sakta hai, par EBS, allocated publicIPv4 aur commitment charges remain. Start/stop app readiness aur non-EBS instance-store data alag risks hain.</p><p>CloudWatch Logs retention lagao: expiry par events markedfor deletion storage billing se nikalte hain; physical deletion typicallyup to 72 hours ya rarelonger. Compliance logs ki approved retention short karke bill green mat karo.</p>',points:['SavingsPlan commitment existing ho toh dev stop se eligible usage kam ho kar unused commitment badh sakta hai; aggregate utilization recalc karo.','Galti jo sab karte hain: automation owner/timezone document kiye bina production tag ko dev schedule mein include karna.','Hands-on: terminal sirf /shopkaro/dev14 days; audit90 days aur current TEST logs unchanged.'],asli:'Off-hours compute save karo; residual storage, IPv4 aur commitment cost count karo.'},
 {q:'Budget ka alert sahi kaise configure aur operate karein?',analogy:'Fuel gauge ka red light kharch batata hai; engine ka universal automatic off switch nahi. Gauge ka wire aur receiver bhi connected chahiye.',body:'<p>Budget → ACTUAL/FORECASTED threshold → SNS/email subscribers → resource policy → receiver/runbook. SNS same account mein ho; budgets.amazonaws.com ko scoped SourceAccount/SourceArn se Publish allow karo. Budget notifications se real email delivery ya spend control automatic prove nahi hota.</p><pre>Measure → owner → preserve value → fix waste\n→ verify resource config + workload → remeasure billing\n→ right-size baseline → stress-test commitment</pre>',points:['Budgets updates typically8–12 hours interval; notification billing latency rakhti hai. Budget Actions selected IAM/SCP/resource actions ho sakte hain, universal hard cap nahi.','Company-scale:40engineers, shared costs allocation, weekly cost/order + error/latency SLO review; CFO target ko outage se meet mat karo.','Interview follow-up: Budget created but no alert? Notification threshold, subscriber, SNS policy, billing delay aur receiver confirmation inspect karo.','Hands-on: interview missing policy + notification fix karo; simulator metadata only, real billing alert nahi bhejta.'],asli:'Alert configuration, receiver operation aur business guardrails teeno verify karo.'}
 ],
 myth:[{myth:'Dev daily 8 hours use hota hai, pattern steady hai toh Reserved lo.',sach:'Isolated 24% weekly utilization par hourly commitment waste ho sakti hai. Schedule OD aur actual aggregate coverage compare karo.'},{myth:'LowCPU means instance safely tiny kar sakte hain.',sach:'Memory, burst credits, network/I/O, peak latency aur HA headroom inspect; benchmark before/after.'},{myth:'Budget 1000 USD banaya toh AWS1000par sab stop kar dega.',sach:'Budget delayed tracking/notifications hai. Selected configured actions broad real-time spend cap nahi.'},{myth:'Delete every old snapshot; gp3 flat 20% cheaper hai.',sach:'Recovery owners/retention preserve. Snapshot billed changed blocks unknown; extra gp3IOPS/throughput savings reduce karte hain.'}],
 playbook:{title:'Meter → owner → preserve → reduce → measure → commit',use:['Usage-type growth: CE + exports + activated tags.','Idle owned inventory: preserve recovery point, then approved cleanup.','Stable optimized baseline: compare hourly SP/service reservation quote.'],avoid:['Deleting last backup, lowering audit retention, removing HA.','100%peak commitment aur discounts ko guaranteed savings samajhna.','Billing alert ko immediate spending cap samajhna.'],how:['Successful-order denominator aur service/usage-type trend define karo.','Owner, data/HA/performance/retention contract read karo.','Fix idle resources and network path; verify resource + workload.','Remeasure delayed billing, stress-test lower future usage, then commit.'],redflags:['EC2 hours same, transferGB sharplyup.','CPUlow, memory/IO/peak data missing.','SP utilization low despite high monthly peak.','Budget exists, notification/subscriber/policy missing.'],rule:'Value preserve karke waste hatao; optimized baseline par hourly commitment lo.'},
 exam:[{cue:'Flexible across EC2 families/Regions + Fargate/Lambda',pick:'Compute Savings Plans (up to66%)'},{cue:'Fixed EC2 family + Region, steady baseline',pick:'EC2 Instance Savings Plans (up to72%)'},{cue:'Eligible databases / serverless database usage commitment',pick:'Database Savings Plans (up to35%; current eligibility check)'},{cue:'Interruptible retry-safe batch',pick:'Spot + checkpoint/idempotency + diverse pools'},{cue:'Right-size recommendations',pick:'Compute Optimizer; adequate metrics + workload test'},{cue:'Threshold vs unusual spend',pick:'Budgets vs Cost Anomaly Detection; both billing delays'},{cue:'Team cost attribution',pick:'Resource tags + activated cost allocation tag keys'},{cue:'Private S3 via NAT',pick:'Review S3 gateway endpoint/route association; retain required internet egress'}],
 stages:[
 {type:'dryrun',title:'🧪 ₹18 lakh bill ke peeche ka path',intro:'Fictional cost investigation; amounts are course story, not measured AWS bill.',goal:'Usage driver pehchano, phir value-preserving change choose karo.',lesson:'Network path, hourly usage aur recovery ownership inspect karne ke baad hi cost action lo.',nodes,edges,panels:[{id:'bill',title:'Bill / unit'},{id:'decision',title:'Decision / preserved value'}],steps:[
 {say:'Orders 50% bade, bill 3× hua. CFO ko cost per order ₹6 se ₹12 dikh raha hai. Service-level total ke baad usage quantity aur rate separate karo.',nodes:{cw:{tone:'busy',badge:'₹18 lakh course story'}},panels:{bill:['September:₹6 lakh /1 lakh successful orders','October:₹18 lakh /1.5 lakh orders'],decision:['Value target: orders SLO + invoice data + HA preserve']}},
 {say:'Warehouse import private apps se same-Region S3 ko NAT ke through bhej raha hai. Processed GB × rate bill badha raha hai. Poora NAT delete karna third-party internet calls tod sakta hai.',flows:[{from:'cw',to:'nat',tone:'bad'}],panels:{bill:['NAT processing quantity up'],decision:['S3 path optimize; required internet path preserve']},ask:Q('Same-Region S3 data ke NAT processing ko avoid karne ka focused action?','S3 gateway endpoint + correct route-table associations; other internet path preserve',['NAT gateways delete karo; private apps ko public third-party endpoints ki zaroorat nahi hoti','S3 ko cross-Region replicate karo; replicated requests automatically all transfer free kar dete hain','Reserved NAT commitment buy karo; compute Savings Plans NAT processing bytes cover karte hain'],0,'Gateway endpoint S3 route ko NAT se hata sakta hai. NAT delete unrelated internet breaks; cross-Region replication newcost; compute SP NAT bytes cover nahi karta.')},
 {say:'Production 1000 GiB gp2 ko same 3000 IOPS aur 250 MiB/s par gp3 karo: capacity $80 + extra throughput $5 ≈$85/month. Old $100 se approx $15 saving; flat 20% full-bill claim galat hai.',flows:[{from:'cw',to:'ebs',tone:'acc'}],panels:{bill:['Approx N.Virginia $100→$85/month','Snapshot cost depends on incremental blocks'],decision:['Same volume ID, data, size, encryption','Explicit3000 IOPS/250 MiB/s target']}},
 {say:'Detached import volume available hai. Owner cleanup approve karta hai, par current invoice TEST data ka fresh completed recovery point pehle chahiye. Last-good production backup aur audit 90-day logs preserve karo.',nodes:{ebs:{tone:'busy',badge:'preserve → delete'}},panels:{bill:['Idle volume still billed'],decision:['Fresh snapshot completion verify','Approved retired objects only']},ask:Q('Available EBS volume delete karne se pehle kya evidence chahiye?','Owner approval, useful data/recovery need aur completed preservation snapshot verify karo',['Available state sufficient hai; unattached volume mein valuable data permanently reh nahi sakta','Old snapshot ka VolumeSize same hai; billed bytes aur current data match automatically proved hain','Cost Explorer mein zero usage line aaye toh volume delete se pehle backup ki zaroorat nahi'],1,'Available means unattached, not disposable. Snapshot VolumeSize billed changed blocks/currentdata proof nahi. Billing data/zero compute use data value establish nahi karte.')},
 {say:'Dev 8 hours on weekdays ko isolated annual commitment se compare karo. Monthly peak ko poore year ka baseline mat samjho. Broader eligible fleet unused commitment absorb kar sakta hai; aggregate hourly reports dekho.',flows:[{from:'cw',to:'ec2',tone:'acc'}],panels:{bill:['8×5 /168≈24% weekly active','Commitment billed every hour'],decision:['Schedule OD + residual storage/IPv4','Rightsize then forecast commitment']},ask:Q('Isolated dev workload24%hours, hypothetical committed rate65% of OD. Better starting point?','Business-hours schedule + On-Demand; committed minimum low utilization par mehnga ho sakta hai',['One-year commitment buy karo; weekly repeat hone wala pattern100%utilization ke barabar hota hai','Savings Plans ke unused weekend hours weekdays par transfer karo; monthly aggregate coverage kaafi hai','Spot-only bina checkpoint use karo; dev labels se unfinished local data automatically recover hota hai'],2,'24% usage<65% break-even example, so scheduled OD cheaper for isolated workload. Repeating schedule not100%, no hourly carryover, Spot retry/data design still needed.')},
 {say:'Budget 1000 USD, ACTUAL 80% notice ke liye subscriber aur scoped SNS Publish policy chahiye. Billing delayed hai. Local resource charges ya automatic delivery prove nahi hue. Resource checks ab karo; actual billing aur receiver operation separately verify karo.',flows:[{from:'cw',to:'sns',tone:'ok'}],nodes:{sns:{tone:'ok',badge:'metadata configured'}},panels:{bill:['No actualAWS invoice generated','EBS+EIP slice estimate≠wholebill 40%cut'],decision:['Preserved data/HA/performance/retention','Alert config + receiver/runbook + laterbilling']}}
 ]},
 {type:'flowlab',title:'🎛️ Hourly commitment aur downturn stress',goal:'Fictional blended workload: peak $100/hour On-Demand equivalent for 8 hours/day; baseline $60/hour for 16 hours/day. At least 30% demand drop par saving ≥25% aur unused commitment ≤5% of paid commitment chahiye.',scenario:'Hypothetical blended rates: 1 year =30% discount, 3 years =45% discount; actual AWS quote/purchase nahi. 730 hours/month; ₹88/USD. Coverage slider On-Demand-equivalent baseline percentage hai. Actual committed USD/hour = covered On-Demand value × (1-discount). Unused hourly commitment expires. Real SP rates/allocation workload ke hisaab se differ karte hain.',knobs:[{id:'coverage',label:'Baseline ka coverage',min:0,max:150,step:25,value:0,unit:'%'},{id:'term',label:'Commitment term',min:0,max:1,step:1,value:0,labels:{0:'1 year, assumed 30% off',1:'3 years, assumed 45% off'}},{id:'drop',label:'Future demand drop',min:0,max:50,step:10,value:0,unit:'%'}],model:k=>{const p=plan(k);return {readouts:[{label:'Actual committed rate',value:'$'+p.C.toFixed(2)+'/hour',tone:'acc'},{label:'Stressed OD/month',value:'$'+p.od.toFixed(0),tone:'acc'},{label:'Committed + overflow/month',value:'$'+p.total.toFixed(0)+' ≈₹'+Math.round(p.total*88).toLocaleString('en-IN'),tone:p.saving>=25?'ok':'bad'},{label:'Saving vs same stressed demand',value:p.saving.toFixed(1)+'%',tone:p.saving>=25?'ok':'bad'},{label:'Unused / paid commitment',value:p.waste.toFixed(1)+'% ($'+p.wasted.toFixed(0)+'/month)',tone:p.waste<=5?'ok':'bad'}],verdict:{ok:p.ok,text:p.ok?'Model fit: stress ≥30%, saving ≥25%, unused ≤5%. Real commitment se pehle actual term/rate aur forecast review karo.':'Coverage/term ko future usage ke against test karo; stress at least 30%, saving 25% aur waste≤5% chahiye.'}};},check:k=>plan(k).ok,lesson:'Monthly average peak se commitment mat lo. Hour-by-hour usage aur lower future demand par unused minimum cost count karo. Discount assumptions yahan teaching inputs hain.'},
 {type:'bins',title:'🧺 Workload → pricing approach',instructions:'Given workload constraints ke hisaab se initial pricing path chuno.',bins:[{id:'od',label:'Schedule / On-Demand'},{id:'commit',label:'Optimized baseline commitment'},{id:'spot',label:'Interruption-tolerant Spot'}],items:[{text:'Isolated dev8 hours on weekdays, forecast uncertain',bin:'od',explain:'About24% weekly utilization; schedule + residualcost compare.'},{text:'Stable optimized24×7 compute, forecast credible',bin:'commit',explain:'Hourly eligible baseline + quote/utilization after rightsizing.'},{text:'Checkpointed retry-safe video batch',bin:'spot',explain:'Interruptions safe; diversify pools and model retries.'},{text:'Two-week proof-of-concept, no lasting baseline',bin:'od',explain:'No annual minimum until need persists.'},{text:'Eligible database baseline, current generation confirmed',bin:'commit',explain:'Compare Database SP/service-specific reservations; Compute SP does not coverDB.'},{text:'Idempotent CI runners, flexible types/AZs',bin:'spot',explain:'Restartable builds can trade availability for price.'}]},
 {type:'order',title:'📋 Value-preserving cost review',instructions:'Measure aur preserve steps ko commitment purchase se pehle rakho.',steps:[{text:'Usage-type trend aur cost per successful order measure',explain:'Total monthly price se quantity/rate separate.'},{text:'Owner + data/HA/performance/retention contract confirm',explain:'Cheap but broken workload optimization nahi.'},{text:'Approved waste/path fix; metrics aur preserved data verify',explain:'Baseline rightsize before fixed commitment.'},{text:'Lower future hourly usage par commitment quote stress-test',explain:'Unused hourly minimum futurebill badha sakta hai.'},{text:'Budget receiver, attribution aur delayed billing remeasure',explain:'Savings claim resource config+actualinvoice se compare.'}]},
 {type:'triage',title:'🩺 EC2 hours same, bill 40%up',symptom:'Alag fictional case: monthly bill 40%up. New cache rollout ke baad CPUsame aur instance count same hai. User latency slightly up.',goal:'Usage quantity se cross-AZ path identify; HA destroy kiye bina locality review.',commands:[{cmd:'aws ce get-cost-and-usage --time-period Start=2026-09-01,End=2026-11-01 --granularity MONTHLY --metrics UnblendedCost --group-by Type=DIMENSION,Key=USAGE_TYPE',out:'Recorded case: BoxUsage hours unchanged; regional/cross-AZ transferred bytes 4×; cache request volume nearunchanged',clue:true,note:'Compute rate alone newbill explain nahi karta.'},{cmd:'aws ec2 describe-instances',out:'App nodes1a+1b, same types/count. Cache clients in1a route all requests to primary cache in 1b.',clue:true,note:'Request payload cross-AZ repeatedly jaa raha hai; service-specific rates check.'},{cmd:'aws logs describe-log-groups',out:'Retention unchanged; current ingest volume near prior period.',clue:false,note:'Logs possible cost driver, par current evidence transfer ko point karta hai.'}],questions:[{"q": "Likely new cost driver kya hai?", "choices": ["Existing EC2 commitment discount hi reduce hua; unchanged hours se transfer quantity ignore kar sakte hain", "Log retention short hui; shorter retention se archival storage cost automatically badh jaati hai", "CloudTrail CPU metric twice bill ho raha hai; CloudTrail application CPU collect karta hai", "Cache ke cross-AZ traffic pattern ka bytes/rate aur client placement investigate karo"], "answer": 3, "explain": "Transfer bytes4× aur client/cache AZ mismatch evidence hai. Discount change ka evidence nahi. Shorter retention cost increase establish nahi karti; CloudTrail API audit hai, CPU collector nahi. Relevant service transfer rates verify karo."}, {"q": "Safe investigation aur fix kaunsa hai?", "choices": ["Client locality, replica/topology aur transfer rates compare karo; HA/consistency preserve karo", "Cache replicas delete karke single AZ banao; availability target cost ke baad decide karna chahiye", "Compute SP buy karo; SP discount applicable compute ke saath har cross-AZ byte bhi cover karta hai", "Private cache ko public IP do; public routing se service paths ki saari cross-AZ charges hat jaati hain"], "answer": 0, "explain": "Locality/service-specific rates ko HA tradeoff ke saath compare karo. Replicas delete karna availability risk, SP network discount nahi, public IP free path nahi. Connection/security/consistency constraints bhi verify karo."}]},
 {type:'terminal',title:'🖥️ Approved waste cleanup — backup ke saath',instructions:'Bounded metadata fixture in N.Virginia; TEST payload contracts are declared. No disk block copy, workload performance, real bill or timed modification runs.',goal:'<p><b>1. Owner/data:</b> <code>cat ownership.json</code> padho. Original two-AZ compute, production/audit volume IDs/data, last-good snapshot, associated EIP aur audit 90-day logs preserve karo.</p><p><b>2. Recovery first:</b> Retired import volume <code>'+WASTE+'</code> ka fresh snapshot banao, phir <code>aws ec2 wait snapshot-completed --snapshot-ids '+NEW+'</code>. Completed snapshot ke baad approved volume aur expired old snapshot <code>'+OLD+'</code> delete karo.</p><p><b>3. Waste fix:</b> Prod <code>'+PROD+'</code> ko same 1000 GiB/encryption/data/attachment par gp3, 3000 IOPS, 250 MiB/s karo. Idle <code>'+IDLE+'</code> release karo. <code>'+LOG+'</code> retention 14 days; current TEST event preserve.</p><p><b>4. Alert + final read:</b> <code>budget.json</code> aur <code>notifications.json</code> se monthly USD 1000 COST budget, ACTUAL 80% SNS notice create karo. Final <code>aws budgets describe-budget --account-id '+ACCT+' --budget-name '+BNAME+'</code>. 9 actions; snapshot ID CLI result se compare karo. Hints exact commands dete hain.</p><p><code>cat prices.json</code> optional scoped model hai: snapshots/logs/compute/network/tax excluded. Historical bill cleanup se turant change nahi hota. Data loss, lower I/O, audit-retention cut aur incomplete alert/read se mission complete nahi hoga.</p>',account:seed(),files:{'budget.json':file(BUDGET),'notifications.json':file(NOTIFICATIONS),'prices.json':file({asOf:'2026-10-28',Region:R,approx:true,gp2GiBMonthUSD:.10,gp3GiBMonthUSD:.08,additionalIOPSMonthUSD:.005,additionalMiBsMonthUSD:.04,publicIPv4HourUSD:.005,hours:730,INRperUSD:88,excludes:['snapshot changed blocks','logs','EC2','network','tax','credits','commitments']}),'ownership.json':file({retiredImport:{volume:WASTE,approval:'Approved TEST fixture cleanup; current TEST invoice must survive fresh completed snapshot',oldSnapshot:OLD},production:{volume:PROD,requiredIOPS:3000,requiredMiBs:250,sizeGiB:1000},audit:{volume:AUDIT,retentionDays:90},protectedRecoveryPoint:KEEP,idleIPv4:IDLE})},tasks,solution,hints:['Ownership aur state read karo: cat ownership.json; aws ec2 describe-volumes; aws ec2 describe-snapshots. Available state disposable data proof nahi.','Fresh snapshot complete hone ke baad retiredvolume delete; gp3explicit performance, idle EIP aur approved snapshot target IDs carefully choose. BudgetJSON aur notifications JSON dono use karo.',solution.join(' → ')],success:AG.allOf(tasks),successText:'Approved waste removed with fresh preserved TEST recovery point. Original production/audit data, HA, associated EIP and 90-day audit retention preserved; gp3 3000 IOPS/250 MiB/s configured. Budget 1000 USD/ACTUAL 80% SNS metadata current read verified. Actual AWS: wait for volume modifications, verify workload/restore and receiver; remeasure delayed billing before claiming total savings.'},
 {type:'docker',title:'🐳 Lab27 — actual APIs, honest billing boundary',project:'27-cost-waste-hunter',goal:'Owned Moto par real CLI snapshot/wait/delete, gp3 same ID, idle EIP, retention, Budget + SNS policy/notification metadata aur scopedcleanup.',why:'Moto EBS disk blocks ya actual bill meter nahi hai. CE response empty; budget subscriber readback unimplemented500. CLI accepted subscriber input/notification list automatic delivery prove nahi karta.',steps:[{text:'Approot se labREADME padho, phir localrunner use karo.',cmd:'./docker-labs/.venv/bin/python -I docker-labs/27-cost-waste-hunter/lab.py',expect:'8 behavior checks, cleanup9, default AMI snapshots preserved, OWNED MOTO STOPPED / LISTENER CLOSED.'},{text:'Volume readback aur retentionTEST compare karo.',expect:'Original 1000 GiB volume gp3/3000 IOPS/250 MiB/s/encrypted; fresh snapshot retained before delete; TEST current log retained.'},{text:'Billing/notification gaps padho.',expect:'Subscriber input accepted; notification list stored; CE ResultsByTime empty. No actual savings, block restore, automatic email or performance claim.'}],observe:Q('Lab27 actually kis claim ko prove karta hai?','Real CLI API metadata transitions aur scoped cleanup; billing/backup block copy/runtime proof nahi',['Moto EBS snapshot ne original filesystem bytes restore karke full backup integrity prove kar di','Budget 1000 USD set hone par Moto actual AWS resource charges ko1000par automatically stop karta hai','Cost Explorer cleanupke turantbaad real monthly invoice recompute karke observed savings deta hai'],1,'Actual metadata/readbacks andTESTlog accepted. Moto no blockdevice/restore; Budget notspendcap; CEempty/nonmeter. Automatic subscriber delivery nottested.')},
 {type:'quiz',title:'🎓 Cost decisions — constraints pehle',questions:[{"q": "Isolated dev workload 8 hours on weekdays chalta hai; next year ka baseline uncertain. Initial approach?", "choices": ["One-year RI lo; weekly repeating schedule se poori hourly commitment consume ho jaati hai", "Compute SP full peak par buy karo; unused weekend minimum weekday usage se adjust ho jaata hai", "Schedule stop/start + On-Demand; residual EBS/IPv4 aur aggregate commitments bhi count karo", "Reserved pricing EBS storage free kar degi; instance ke active hours compare karna zaroori nahi"], "answer": 2, "explain": "Low isolated utilization par scheduled On-Demand compare karo. Repeating hours full-time usage nahi, unused commitment hourly carry nahi hoti, aur compute discounts storage free nahi karte. Broader eligible fleet result badal sakta hai."}, {"q": "Team EC2 families/Regions badal sakti hai; Fargate/Lambda migration bhi planned hai. Baseline commitment?", "choices": ["EC2 Instance Savings Plans; fixed family aur Region ka commitment har Fargate task bhi cover karega", "Database Savings Plans; Lambda business logic data process karti hai, isliye invocation eligible hoga", "On-Demand Capacity Reservation; capacity booking har Region mein sabse bada price discount deta hai", "Compute Savings Plans; eligible compute par flexibility, actual rate aur hourly utilization verify karo"], "answer": 3, "explain": "Compute SP EC2, Fargate aur Lambda usage par flexible hai. EC2 Instance SP family/Region scoped; Database SP eligible DB usage ke liye hai. ODCR capacity reserve karta hai, automatic discount nahi deta. SP capacity guarantee nahi hai."}, {"q": "Eligible RDS/Aurora/DynamoDB usage ke liye current commitment option kaunsa hai?", "choices": ["Database Savings Plans ki eligibility/rate compare karo; Compute SP database usage cover nahi karta", "Compute Savings Plans use karo; managed RDS compute hai, isliye saare RDS instances eligible hain", "EC2 Instance Savings Plans lo; managed DB ke underlying EC2 family ko customer select karta hai", "Spot RDS reservation lo; Multi-AZ standby interruption ke har effect ko bina impact absorb karta hai"], "answer": 0, "explain": "Current Database SP eligible database usage par up to35%, 1-year no-upfront option hai; service/generation check karo. Compute SP managed DB usage cover nahi karta, EC2 Instance SP managed RDS par nahi lagta. Spot RDS reservation yahan valid product nahi."}, {"q": "1000 GiB gp2 $100/month se gp3 $80 capacity + $5 required throughput par gaya. Saving?", "choices": ["Approx $20/month (20%); baseline se upar throughput bhi capacity charge mein included hota hai", "Approx $15/month (15%); extra provisioned I/O count karo aur workload performance verify karo", "Approx $25/month (25%); provisioned throughput ko compute discount se subtract karna hota hai", "Approx $100/month (100%); gp3 par attached volume ki capacity ke liye separate bill nahi aata"], "answer": 1, "explain": "100-(80+5)=15. Capacity-only20% calculation extra throughput ignore karti hai. Koi compute-discount subtraction ya free attached EBS nahi. Actual limits, workload aur final invoice verify karne padenge."}, {"q": "Resources par team tag hai, billing report mein absent. Pehla check?", "choices": ["Tag values lowercase karo; billing activation ki zaroorat sirf AWS-generated tags ko hoti hai", "Har resource reboot karo; tag keys instance boot ke waqt billing account mein register hote hain", "Billing mein tag key activation, discovery/activation delay aur report period/backfill inspect karo", "Cost Explorer mein CPUCreditBalance metric chuno; allocation tags CloudWatch dimensions hote hain"], "answer": 2, "explain": "User-defined tag billing activation alag action hai. Discovery aur activation up to24h each le sakte hain. Case normalization owner consistency mein help kar sakti hai, par activation replace nahi karti. Reboot aur CPUCreditBalance billing tag activation nahi hain."}, {"q": "Budget 80% alert configured, spend cross hua, par immediate alert nahi. Kya inspect karoge?", "choices": ["Budget cross hone par AWS new charges block karta hai; notification receipt ka role sirf audit hai", "Budget amount automatically EC2 stop action hota hai; actual stop aur console display mein delay hai", "SNS topic kisi account mein ho sakta hai; budget notification ke liye Publish policy required nahi", "Billing delay, notice/subscriber, SNS policy aur receiver; Budget real-time hard cap nahi hai"], "answer": 3, "explain": "Budget updates/billing lag aata hai; configuration aur receiver inspect karo. Budget automatically all charges block ya EC2 stop nahi karta. Budget SNS topic same account mein aur required Publish policy ke saath hona chahiye. Metadata acceptance delivery proof nahi."}, {"q": "EC2 CPU10%, memory95%, p99 latency SLO ke paas. Right-size action?", "choices": ["Memory/I/O/network/peak data, recommendation aur load test dekho; CPU alone par downsize mat karo", "vCPU count quarter kar do; low CPU unused RAM aur network/storage headroom bhi establish karta hai", "T-family micro par shift karo; CPU credits har memory pressure aur network bottleneck ko handle karte hain", "Ek AZ replica hata do; current low CPU se remaining AZ ki failure capacity automatically prove ho gayi"], "answer": 0, "explain": "CPU alone insufficient hai. Memory pressure, p99 aur failure headroom assess karo. CPU credits RAM ko solve nahi karte; low CPU network/storage capacity prove nahi karta. Replica deletion HA break kar sakta hai. Measured before/after test chahiye."}, {"q": "EBS volume available hai; old snapshot bhi hai. Safe cleanup evidence?", "choices": ["Available means AWS valuable data erase kar chuka hai; old snapshot ka reference cleanup ke liye kaafi hai", "Owner approval, current data/recovery need aur completed preservation snapshot verify; last backup keep", "Snapshot VolumeSize se actual stored incremental bytes aur current data match dono establish ho jaate hain", "Oldest snapshots pehle delete karo; newer snapshot ka hona required recovery coverage prove kar deta hai"], "answer": 1, "explain": "Available sirf unattached hai. Snapshot VolumeSize actual billed changed blocks ya current restored data prove nahi karta. Age alone cleanup criterion nahi; approved recovery points/retention chahiye. Metadata emulator actual filesystem restore integrity prove nahi karta."}]}
 ],
 interview:{title:'Interview — preservevalue aur alertrepair',instructions:'4decisions, phir missingbudget alertconfig fix. Real messages nahi bheje jaate.',questions:[
{"q": "Budget 1000 USD hai, notification list empty aur SNS Publish policy missing. Repair?", "choices": ["Budget amount double karo; higher limit se missing notification aur subscriber automatically create honge", "Cost Explorer refresh ek minute kar do; polling rate budget ke SNS resource policy ko override karta hai", "Notification + subscriber aur scoped SNS policy add karo; current config aur receiver verify karo", "Manual SNS Publish test kar do; caller ki success Budgets service ki Publish permission bhi prove karti hai"], "answer": 2, "explain": "Budget definition alert wiring create nahi karti. Notice/subscriber aur budgets.amazonaws.com Publish policy chahiye. Limit/CE refresh wiring repair nahi; manual caller permission service permission se alag hai. Actual receiver/delivery separately verify karo."},
{"q": "SP baseline $50/hour tha; rightsizing ke baad eligible usage $30/hour. Kya review karoge?", "choices": ["Unused $20/hour next month carry hoga; current hourly utilization ka final bill par effect nahi hoga", "Rightsizing se Savings Plan contract automatically $30/hour ho jaata hai; separate review required nahi", "Monthly peak $50/hour cross kare toh idle hours ki poori commitment consume maana jaata hai", "Hourly coverage/utilization aur remaining commitment; excess minimum abhi bhi payable ho sakta hai"], "answer": 3, "explain": "Contract minimum persist karta hai; unused hourly amount carry nahi hota. Rightsize before buying, aggregate eligible usage aur remaining commitment inspect karo. No automatic contract reduction ya monthly-peak netting. Actual rates/usage allocation calculate karo."},
{"q": "Private app ka S3 traffic NAT processing badha raha hai; app third-party API bhi call karta hai. Focused fix?", "choices": ["S3 gateway endpoint ki routes/policy verify karo; required internet path aur workload preserve karo", "NAT delete karke S3 public karo; public bucket private apps ke liye third-party internet path bana deta hai", "Compute SP NAT processing par lagao; SP discount har network service ke processed GB par apply hota hai", "App ko single AZ mein consolidate karo; gateway endpoint ko high availability ke saath use nahi kar sakte"], "answer": 0, "explain": "Gateway endpoint S3 path ko NAT se hata sakta hai; doosre internet calls ka path still chahiye. Public bucket route nahi banata; SP NAT processing cover nahi karta; single-AZ consolidation HA break kar sakti hai. Policy/routes/workload verify karo."},
{"q": "Spot worker graceful handling ke liye guaranteed2-minute notice maan sakte hain?", "choices": ["Har interruption par exact2-minute warning guaranteed hai; hibernation bhi poore2minute wait karta hai", "Notices best effort; stop/terminate generally2min, hibernate immediate; checkpoint/retry design chahiye", "EC2 Spot interruption notice emit nahi karta; EventBridge aur IMDS sirf On-Demand ke liye hain", "Savings Plan Spot par lagao; discount ke saath interruption window aur compute capacity guaranteed hain"], "answer": 1, "explain": "Stop/terminate warning generally2minutes aur best effort hai. Hibernation immediately start hoti hai. EventBridge/IMDS interruption notice dete hain. SP Spot discount ya capacity guarantee nahi; workload fault tolerance phir bhi required hai."},
 {terminal:{type:'terminal',title:'🖥️ Budget exists, alert missing',instructions:'Optimized inventory/data already safe. Budget 1000 USD exists; SNS Publish policy and notification missing. Fix metadata, send no real message.',goal:'<p>3 actions: <code>budget-topic-policy.json</code> SNS Policy set karo; <code>threshold80.json</code> + <code>subscribers.json</code> se standalone budget notification create karo; full current <code>describe-notifications-for-budget</code> final read. Existing resource/data/retention/budget limit preserve. <code>get-topic-attributes</code> aur <code>describe-budget</code> optional inspection.</p>',account:interviewSeed(),files:{'budget-topic-policy.json':file(POLICY),'threshold80.json':file(NOTICE),'subscribers.json':file(SUBS)},tasks:itasks,solution:isolution,hints:['Budget definition, notice, subscriber aur SNS service permission four pieces hain; missing metadata identify karo.','SNS Policy requires budgets.amazonaws.com with SourceAccount and SourceArn. Existing Budget ko delete karne ki zaroorat nahi.',isolution.join(' → ')],success:AG.allOf(itasks),successText:'Original inventory preserved; Budget ACTUAL 80% SNS notification and scoped publish policy configured; current read verified. Automatic delivery/real spend cap not proved; real AWS receiver confirmation aur billing delay monitor karo.'}}
 ]},success:['Usagequantity/rate aur cost per order se cause explain kar sakta hoon.','Data/HA/performance/retention preserve karke approvedwaste remove kar sakta hoon.','Hourly commitment stress-test aur Budget alert wiring explain kar sakta hoon.'],homework:'<p>Optional real AWS, explicit account/cost approval ke baad: billing ka read-only audit karke top usage driver identify karo. Proposed action ka owner, forecast, rollback aur SLO check likho. Commitment purchase, production deletion aur actual notifications bina approval mat karo. Disposable lab cleanup mein sirf owned volumes, snapshots, EIP, logs, Budget aur SNS topic remove; billing exports/retained backups ka owner separately review. Moto run actual billing proof nahi.</p>',cards:[
 {front:'Cost per order?',back:'Relevant cost / successful orders. Same period ka quantity, rate, shared-cost allocation aur SLO compare karo.'},
 {front:'Compute SP vs EC2 Instance SP?',back:'Compute SP up to66%: EC2 families/Regions + Fargate/Lambda. EC2 Instance SP up to72%: fixed family/Region. Hourly commitment, capacity reservation nahi.'},
 {front:'Database Savings Plans?',back:'Current eligible database usage up to35%, 1-year no-upfront. Service/generation eligibility check; same-usage RI discount stack nahi hota.'},
 {front:'Business-hours dev?',back:'Scheduled On-Demand compare karo. Isolated low utilization commitment waste kar sakti hai. EBS/IPv4/existing commitment stopped compute ke baad bhi payable.'},
 {front:'gp2 → gp3 saving?',back:'Approx N.Virginia capacity .10→.08 USD/GiB-month; extra IOPS/throughput count karo. Required performance, original ID/data preserve; actual workload test chahiye.'},
 {front:'Budget vs Anomaly?',back:'Budget threshold/forecast; Anomaly Detection unusual billing pattern. Dono billing delays rakhte hain; universal real-time spending cap nahi.'},
 {front:'Available EBS disposable?',back:'Unattached ka matlab worthless nahi. Owner approval, current recovery need, completed preservation snapshot; last-good backup preserve karo.'},
 {front:'SP unused commitment?',back:'Actual committed USD/hour unused hone par bhi charged; hourly carryover nahi. Baseline right-size aur lower future demand par stress test pehle.'}
 ]
 }]);
})();
